import FoundationModels

@Generable(name: "Recipe", description: "A recipe")
struct Dish {
    /// The dish's name.
    var title: String
    let servings: Int
    @Guide(description: "Steps")
    var steps: [String]
    @Guide(.minimum(1), .maximum(5))
    var rating: Int
    @Guide(.anyOf(["a", "b"]))
    var letter: String
    @Guide(description: "Code", #/[A-Z]{3}/#)
    var code: String
    var  spaced  :  Bool
    var flag: Bool = false
    static var shared: Int = 0
    var computed: Int { 1 }
    var nested: [[Int]]
    var optionalList: [String]?
}

@Generable(representNilExplicitlyInGeneratedContent: true)
struct Explicit {
    var maybe: Int?
}

@Generable
fileprivate struct Hidden {
    var a: Int
}

@Generable
internal struct Internal {
    internal var a: Int
    private var b: Int
}

@available(iOS 26.0, *)
@Generable
struct Available {
    var a: Int
}

enum Outer {
    @Generable
    struct Inner {
        var a: Int
    }
}
